mapper.update:
update play_bingo_card
   set filled_mask = filled_mask | #{bit},
       update_time = #{updateTime}
 where member_id = #{memberId} and topic_id = #{topicId}
   and (filled_mask & #{bit}) = 0

update play_bingo_card
   set reward_mask = reward_mask | #{tierBits},
       update_time = #{updateTime}
 where member_id = #{memberId} and topic_id = #{topicId}
   and (reward_mask & #{tierBits}) <> #{tierBits}
